#include "../src/AlphaSimulation.h"
using namespace alpha;
int checks=0;void check(bool value,const char* label){if(!value)throw std::runtime_error(label);++checks;std::cout<<"PASS "<<label<<'\n';}
int main(){try{
 int previous=0;
 for(int faction=0;faction<2;++faction){previous=0;for(int n=0;n<missionCount;++n){World w;w.startLegacyMission(n,faction);int area=w.cols*w.rows;check(area>previous,"each mission grows for both factions");previous=area;check(w.entities.size()<4096,"regional map remains within validated save entity limit");int trees=0,remote=0;for(const auto& e:w.entities)if(e.hp>0&&e.kind==Kind::Forest){++trees;if(e.pos.x>w.width()*.7f||e.pos.y>w.height()*.7f)++remote;}check(trees>100&&remote>20,"regional forests populate distant territory");if(n==0){check(w.missionTarget().x>2900,"abandoned village is relocated far beyond old position");auto worker=w.get(2);check(w.path(*worker,w.missionTarget()),"village courtyard remains reachable along extended route");check(w.train(1,Kind::Worker),"first worker can train before farm objective for either faction");}}
 }
 World w;w.startLegacyMission(0);w.raidsEnabled=false;w.gold=w.wood=1000;int mine=-1,tree=-1;float best=1e9;for(const auto& e:w.entities)if(e.hp>0&&e.kind==Kind::Mine&&distance(e.pos,w.get(1)->pos)<best){mine=e.id;best=distance(e.pos,w.get(1)->pos);}best=1e9;for(const auto& e:w.entities)if(e.hp>0&&e.kind==Kind::Forest&&distance(e.pos,w.get(1)->pos)<best){tree=e.id;best=distance(e.pos,w.get(1)->pos);}check(tree>=0&&mine>=0,"base has accessible finite economy");int startWood=w.wood,startGold=w.gold;w.gather(*w.get(2),tree);w.gather(*w.get(3),tree);w.gather(*w.get(4),mine);w.gather(*w.get(5),mine);for(int i=0;i<2400;++i)w.step(.05f);check(w.wood>startWood+80&&w.gold>startGold+80,"workers repeatedly reach trees and return to command without farm");check(w.missionStage==0,"resource work is allowed before farm objective completion");
 World tight;tight.reset();tight.raidsEnabled=false;tight.entities.clear();tight.add(Kind::Hall,0,{400,500});tight.add(Kind::Hall,1,{2000,500});tight.add(Kind::Forest,-1,{490,500});int trapped=tight.add(Kind::Worker,0,{470,500});tight.move(*tight.get(trapped),{800,700});for(int i=0;i<300;++i)tight.step(.05f);check(tight.get(trapped)&&tight.get(trapped)->pos.x>700,"worker escapes blocked starting cell between tree and command");
 World corner;corner.reset();corner.raidsEnabled=false;corner.entities.clear();corner.add(Kind::Hall,0,{200,200});corner.add(Kind::Hall,1,{2100,200});corner.resizeMap(64,40);corner.terrain[10+10*corner.cols]=Terrain::Rock;int walker=corner.add(Kind::Worker,0,{380,420});corner.move(*corner.get(walker),{460,500});for(int i=0;i<100;++i)corner.step(.05f);check(distance(corner.get(walker)->pos,{460,500})<15,"worker rounds obstacle corner without cutting into blocked cell");
 World crowd;crowd.reset();crowd.raidsEnabled=false;crowd.entities.clear();crowd.add(Kind::Hall,0,{200,200});crowd.add(Kind::Hall,1,{2100,200});crowd.add(Kind::Soldier,0,{600,500});int carrier=crowd.add(Kind::Worker,0,{500,500});crowd.move(*crowd.get(carrier),{800,500});for(int i=0;i<160;++i)crowd.step(.05f);check(crowd.get(carrier)->pos.x>750,"worker does not deadlock against an idle allied soldier");
 std::cout<<"SUCCESS "<<checks<<" progressive regions and free economy checks\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
